 "new_string": "from decimal import Decimal

from src.billing.tax import line_total, tax_for


def test_line_total():
    assert line_total([{"quantity": 2, "unit_cents": 150}]) == 300


def test_tax_for_rounds_half_even():
    assert tax_for(50, "0.25") == 12  # 12.5 -> 12
    assert tax_for(70, "0.25") == 18  # 17.5 -> 18
    assert tax_for(1000, Decimal("0.0825")) == 82  # 82.5 -> 82


def test_tax_for_float_rate_is_exact():
    assert tax_for(1000, 0.0825) == 82
    assert isinstance(tax_for(1000, 0.0825), int)"
}

